param([Parameter(Mandatory)][string]$OutputPath,[Parameter(Mandatory)][string]$WorkRoot,[int]$StartAt=0)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}

function Mark-Call([string]$Phase,$Source,[int]$Index,[int]$Count,[int]$Capacity,[bool]$Flush){$record=[ordered]@{context=$script:caseContext;utc=[DateTime]::UtcNow.ToString('o');phase=$Phase;source=[int[]]$Source;index=$Index;count=$Count;capacity=$Capacity;flush=$Flush};[IO.File]::WriteAllText((Join-Path $WorkRoot 'progress.json'),($record|ConvertTo-Json -Depth 8 -Compress))}
function Seed-Call($Encoder,[char[]]$Source,[byte[]]$Destination){Mark-Call 'seed' $Source 0 $Source.Length $Destination.Length $false;try{return [ordered]@{ok=$true;count=$Encoder.GetBytes($Source,0,$Source.Length,$Destination,0,$false)}}catch{return Failure-Of $_}}
function Convert-Call([string]$Phase,$Encoder,[char[]]$Source,[int]$Index,[int]$Count,[byte[]]$Destination,[int]$Offset,[int]$Capacity,[bool]$Flush){
 Mark-Call $Phase $Source $Index $Count $Capacity $Flush;$cu=-71;$bu=-72;$done=$true
 try{$Encoder.Convert($Source,$Index,$Count,$Destination,$Offset,$Capacity,$Flush,[ref]$cu,[ref]$bu,[ref]$done);$result=[ordered]@{ok=$true}}catch{$result=Failure-Of $_};$result.charsUsed=$cu;$result.bytesUsed=$bu;$result.completed=$done;$result.remaining=$Encoder.FallbackBuffer.Remaining;return $result
}
$replacements=@(@(),@(0),@(65,0),@(0,66),@(65,0,66),@(55296,56320),@(65,0,55296,56320),@(55296,56320,0,65),@(0,55296,56320,0));$inputs=@(@(),@(65),@(55296),@(56320),@(55296,65),@(55296,56320),@(65,55296),@(56320,55296));$seeds=@(@(),@(55296));$profileNumber=-1;$caseNumber=0
foreach($big in @($false,$true)){foreach($replacement in $replacements){$profileNumber++;$owner=[Text.Encoding]([Text.UnicodeEncoding]::new($big,$true,$false)).Clone();$owner.EncoderFallback=[Text.EncoderReplacementFallback]::new([string]::new([char[]][int[]]$replacement))
 foreach($seedId in 0..1){foreach($sourceId in 0..7){foreach($flush in @($false,$true)){foreach($capacity in @(0,1,2,3,4,5,6,8)){foreach($offset in @(0,2)){
  $caseId=$caseNumber;$caseNumber++;if($caseId -lt $StartAt){continue};$seed=[int[]]$seeds[$seedId];$units=[int[]]$inputs[$sourceId];$script:caseContext=[ordered]@{caseId=$caseId;profile=$profileNumber;bigEndian=$big;replacement=[int[]]$replacement;encode=$true;stateful=$true;seed=$seed;source=$units;flush=$flush;capacity=$capacity;offset=$offset}
  $encoder=$owner.GetEncoder();$seedDest=[byte[]](@(99)*16);$seedResult=Seed-Call $encoder ([char[]]$seed) $seedDest;$source=[char[]](@(56320)+$units+@(55296));$dest=[byte[]](@(99)*($offset+$capacity+3));$first=Convert-Call 'first' $encoder $source 1 $units.Length $dest $offset $capacity $flush
  $used=if($first.ok){[int]$first.charsUsed}else{0};$next=[byte[]](@(99)*32);$second=Convert-Call 'second' $encoder $source (1+$used) ($units.Length-$used) $next 0 32 $true;$tail=[byte[]](@(99)*16);$third=Convert-Call 'third' $encoder ([char[]]@(56320,55296)) 1 0 $tail 0 16 $true;$buffer=@()
  foreach($operation in @('remaining','next','remaining','previous')){try{$n=switch($operation){'remaining'{$encoder.FallbackBuffer.Remaining};'next'{[int]$encoder.FallbackBuffer.GetNextChar()};'previous'{[int]$encoder.FallbackBuffer.MovePrevious()}};$result=[ordered]@{ok=$true;count=$n}}catch{$result=Failure-Of $_};$result.remaining=$encoder.FallbackBuffer.Remaining;$buffer+=@([ordered]@{operation=$operation;result=$result})}
  $row=[ordered]@{seed=$seed;source=[int[]]$source;start=1;count=$units.Length;flush=$flush;capacity=$capacity;offset=$offset;seedResult=$seedResult;seedAfter=[int[]]$seedDest;first=$first;after=[int[]]$dest;second=$second;secondAfter=[int[]]$next;third=$third;thirdAfter=[int[]]$tail;buffer=$buffer};$entry=[ordered]@{caseId=$caseId;profile=$profileNumber;bigEndian=$big;replacement=[int[]]$replacement;row=$row};[IO.File]::AppendAllText((Join-Path $WorkRoot 'returned.jsonl'),($entry|ConvertTo-Json -Depth 19 -Compress)+"`n",[Text.UTF8Encoding]::new($false))
 }}}}}
}}
[IO.File]::WriteAllText($OutputPath,([ordered]@{totalCases=$caseNumber;profiles=$profileNumber+1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash}|ConvertTo-Json -Compress))
